}

const LAYOUT_THEME = {
  DEFAULT: "default",
  SAAS: "saas",
  CORPORATE: "corporate",
  GALAXY: "galaxy",
  MATERIAL: "material",
  CREATIVE: "creative",
  MINIMAL: "minimal",
  MODERN: "modern",
  INTERACTIVE: "interactive",
  CLASSIC: "classic",
  VINTAGE: "vintage",
}

